editorial:
Store the minimum pair (value,index) for every power-of-two block. Build each larger block from two halves. For length d, use two length-2^floor(log₂ d) blocks, anchored at the left and right ends. Together they cover the whole range. Overlap is harmless because taking the minimum of the same pair twice does not change it. Time O(n log n+q), space O(n log n).
~~~
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false); cin.tie(nullptr);
    int n,q; cin>>n>>q;
    vector<int>lg(n+1);
    for (int i=2;i<=n;++i) lg[i]=lg[i/2]+1;
    vector<vector<pair<int,int>>>table(lg[n]+1,vector<pair<int,int>>(n));
    for (int i=0;i<n;++i) {
        cin>>table[0][i].first;
        table[0][i].second=i+1;
    }
    for (int k=1;k<=lg[n];++k)
        for (int i=0;i+(1<<k)<=n;++i)
            table[k][i]=min(table[k-1][i],table[k-1][i+(1<<(k-1))]);
    while (q--) {
        int l,r; cin>>l>>r;
        int k=lg[r-l+1];
        auto [value,position]=min(table[k][l-1],table[k][r-(1<<k)]);
        cout<<value<<' '<<position<<'\n';
    }
}
